ALTER TABLE "agent_preferences" ADD COLUMN "display_name" text;--> statement-breakpoint
ALTER TABLE "agent_preferences" ADD COLUMN "tone" text;--> statement-breakpoint
CREATE UNIQUE INDEX "agent_preferences_user_display_name_idx" ON "agent_preferences" USING btree ("user_id",lower("display_name")) WHERE "agent_preferences"."display_name" is not null;--> statement-breakpoint
ALTER TABLE "agent_preferences" ADD CONSTRAINT "agent_preferences_display_name_check" CHECK ("agent_preferences"."display_name" is null or (char_length("agent_preferences"."display_name") between 1 and 40 and "agent_preferences"."display_name" = btrim("agent_preferences"."display_name")));--> statement-breakpoint
ALTER TABLE "agent_preferences" ADD CONSTRAINT "agent_preferences_tone_check" CHECK ("agent_preferences"."tone" is null or "agent_preferences"."tone" in ('warm', 'formal'));